## 2. database.js - 数据库配置（含密码哈希说明）

```javascript
const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const bcrypt = require('bcrypt');

// ============================================
// 安全说明：
// 本系统**密码绝不以明文存储**。数据库中仅保存
// 使用 bcrypt 算法生成的密码哈希值（带盐）。
// 在验证登录时，我们比对的是用户输入的密码
// 经过同样哈希处理后的结果，而非明文密码。
// ============================================

const db = new sqlite3.Database(path.join(__dirname, 'user.db'), (err) => {
    if (err) {
        console.error('数据库连接失败:', err.message);
    } else {
        console.log('已连接到SQLite数据库');
        initDatabase();
    }
});

// 初始化数据库
function initDatabase() {
    db.serialize(() => {
        // 创建用户表（仅包含登录所需字段）
        // 注意：字段命名为 password_hash，强调存储的是哈希值而非明文
        db.run(`
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,  -- 此字段存储bcrypt哈希，绝不存明文
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        `, (err) => {
            if (err) {
                console.error('创建表失败:', err.message);
            } else {
                console.log('用户表已准备好');
                // 创建默认测试用户（可选）
                createTestUser();
            }
        });
    });
}

// 创建默认测试用户
async function createTestUser() {
    const username = 'testuser';
    const password = 'test123';

    db.get('SELECT id FROM users WHERE username = ?', [username], async (err, row) => {
        if (!row) {
            try {
                // 对密码进行 bcrypt 哈希处理（含随机盐）
                // 哈希前先加盐，防止彩虹表攻击
                const salt = await bcrypt.genSalt(10);
                const hash = await bcrypt.hash(password, salt);

                // 只将哈希值存入数据库
                db.run(
                    'INSERT INTO users (username, password_hash) VALUES (?, ?)',
                    [username, hash],
                    (err) => {
                        if (err) {
                            console.error('创建测试用户失败:', err.message);
                        } else {
                            console.log(`测试用户已创建 (${username}/${password})`);
                            console.log('密码已通过bcrypt哈希存储，未保存明文。');
                        }
                    }
                );
            } catch (err) {
                console.error('生成密码哈希失败:', err.message);
            }
        }
    });
}

module.exports = db;
