## 3. server.js - Express 主应用（含密码验证说明）

```javascript
const express = require('express');
const path = require('path');
const bcrypt = require('bcrypt');
const db = require('./database');

const app = express();
const PORT = process.env.PORT || 3000;

// 中间件
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// 静态文件
app.use(express.static('public'));

// 登录页面路由
app.get('/', (req, res) => {
    res.sendFile(path.join(__dirname, 'public', 'login.html'));
});

/**
 * 登录接口
 * 安全说明：
 * 1. 数据库存储的 password_hash 是 bcrypt 哈希，不是明文密码。
 * 2. 验证时使用 bcrypt.compare() 将用户输入的明文密码
 *    与数据库中的哈希进行比对，全程不涉及明文密码的存储或传输。
 */
app.post('/api/login', (req, res) => {
    const { username, password } = req.body;

    // 验证输入
    if (!username || !password) {
        return res.status(400).json({
            success: false,
            message: '请提供用户名和密码'
        });
    }

    // 查询用户
    db.get('SELECT * FROM users WHERE username = ?', [username], async (err, user) => {
        if (err) {
            console.error('数据库查询错误:', err);
            return res.status(500).json({
                success: false,
                message: '服务器错误'
            });
        }

        // 用户不存在
        if (!user) {
            return res.status(401).json({
                success: false,
                message: '用户名或密码不正确'
            });
        }

        try {
            // 使用 bcrypt.compare() 进行哈希比对
            // 而非直接与存储的明文比较
            const isMatch = await bcrypt.compare(password, user.password_hash);

            if (!isMatch) {
                return res.status(401).json({
                    success: false,
                    message: '用户名或密码不正确'
                });
            }

            // 登录成功 - 返回用户信息，但不包含任何敏感数据
            res.json({
                success: true,
                message: '登录成功',
                user: {
                    id: user.id,
                    username: user.username
                }
            });

        } catch (bcryptErr) {
            console.error('密码验证错误:', bcryptErr);
            res.status(500).json({
                success: false,
                message: '服务器错误'
            });
        }
    });
});

// 错误处理中间件
app.use((err, req, res, next) => {
    console.error('服务器错误:', err);
    res.status(500).json({
        success: false,
        message: '服务器内部错误'
    });
});

// 启动服务器
app.listen(PORT, () => {
    console.log(`服务器已启动: http://localhost:${PORT}`);
});

// 关闭数据库连接
process.on('SIGINT', () => {
    db.close((err) => {
        if (err) {
            console.error('关闭数据库失败:', err.message);
        }
        console.log('数据库连接已关闭');
        process.exit(0);
    });
});
```

