## 2. 数据库模块

### database.js
```javascript
const sqlite3 = require('sqlite3').verbose();
const bcrypt = require('bcrypt');

// 创建数据库连接
const db = new sqlite3.Database('./users.db', (err) => {
  if (err) {
    console.error('数据库连接错误:', err.message);
  } else {
    console.log('已连接到 SQLite 数据库');
    initDb();
  }
});

// 初始化数据库表
function initDb() {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      last_login DATETIME
    )
  `, (err) => {
    if (err) {
      console.error('创建表失败:', err.message);
    } else {
      console.log('数据库表已就绪');
      // 创建默认管理员账号（可选）
      createDefaultAdmin();
    }
  });
}

// 创建默认管理员账号（用户名: admin, 密码: admin123）
async function createDefaultAdmin() {
  const adminExists = await getUserByUsername('admin');
  if (!adminExists) {
    // 密码通过 bcrypt 哈希存储，绝不保存明文密码
    const passwordHash = await bcrypt.hash('admin123', 10);
    db.run(
      'INSERT INTO users (username, password_hash) VALUES (?, ?)',
      ['admin', passwordHash],
      (err) => {
        if (err) {
          console.error('创建管理员失败:', err.message);
        } else {
          console.log('默认管理员账号已创建 (用户名: admin, 密码: admin123)');
        }
      }
    );
  }
}

// 根据用户名查找用户
function getUserByUsername(username) {
  return new Promise((resolve, reject) => {
    db.get('SELECT * FROM users WHERE username = ?', [username], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

// 根据用户ID查找用户
function getUserById(id) {
  return new Promise((resolve, reject) => {
    db.get('SELECT * FROM users WHERE id = ?', [id], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

// 更新最后登录时间
function updateLastLogin(userId) {
  return new Promise((resolve, reject) => {
    db.run(
      'UPDATE users SET last_login = CURRENT_TIMESTAMP WHERE id = ?',
      [userId],
      function (err) {
        if (err) reject(err);
        else resolve(this.changes);
      }
    );
  });
}

// 验证密码（使用 bcrypt 比较哈希值）
async function verifyPassword(user, password) {
  // 将用户输入的明文密码与存储的哈希密码进行比较
  return await bcrypt.compare(password, user.password_hash);
}

module.exports = {
  db,
  getUserByUsername,
  getUserById,
  updateLastLogin,
  verifyPassword
};
```

