## 4. 主服务器文件

### server.js
```javascript
const express = require('express');
const session = require('express-session');
const bodyParser = require('body-parser');
const path = require('path');
const database = require('./database');
const { requireAuth } = require('./middleware/auth');

const app = express();
const PORT = process.env.PORT || 3000;

// 中间件配置
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, 'public')));

// 会话配置
app.use(session({
  secret: 'your-secret-key-here', // 生产环境请使用环境变量
  resave: false,
  saveUninitialized: true,
  cookie: {
    maxAge: 24 * 60 * 60 * 1000, // 24小时
    httpOnly: true,
    secure: false // 生产环境改为 true (要求HTTPS)
  }
}));

// 路由：首页
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'login.html'));
});

// 路由：登录页面
app.get('/login', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'login.html'));
});

// 路由：仪表盘（需要登录）
app.get('/dashboard', requireAuth, (req, res) => {
  // 简化版仪表盘，仅显示登录成功信息
  res.send(`
    <h1>欢迎，${req.session.username}！</h1>
    <p>您已成功登录</p>
    <a href="/">返回登录页</a>
  `);
});

// API：用户登录
app.post('/api/login', async (req, res) => {
  try {
    const { username, password } = req.body;

    if (!username || !password) {
      return res.status(400).json({ error: '请输入用户名和密码' });
    }

    // 查找用户
    const user = await database.getUserByUsername(username);
    if (!user) {
      return res.status(401).json({ error: '用户名或密码错误' });
    }

    // 验证密码（使用 bcrypt 比较哈希值）
    const isValid = await database.verifyPassword(user, password);
    if (!isValid) {
      return res.status(401).json({ error: '用户名或密码错误' });
    }

    // 更新最后登录时间
    await database.updateLastLogin(user.id);

    // 设置会话
    req.session.userId = user.id;
    req.session.username = user.username;

    res.json({
      message: '登录成功',
      user: {
        id: user.id,
        username: user.username
      }
    });
  } catch (error) {
    console.error('登录错误:', error);
    res.status(500).json({ error: '服务器内部错误' });
  }
});

// 启动服务器
app.listen(PORT, () => {
  console.log(`服务器运行在 http://localhost:${PORT}`);
});
```

