### database.js
```javascript
const sqlite3 = require('sqlite3').verbose();
const bcrypt = require('bcrypt');

// 创建数据库连接
const db = new sqlite3.Database('./users.db', (err) => {
  if (err) {
    console.error('数据库连接错误:', err.message);
  } else {
    console.log('已连接到 SQLite 数据库');
    initDb();
  }
});

// 初始化数据库表
function initDb() {
  db.run(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `, (err) => {
    if (err) {
      console.error('创建表失败:', err.message);
    } else {
      console.log('数据库表已就绪');
      // 创建默认测试账号（可选）
      createDefaultUser();
    }
  });
}

// 创建默认测试账号（用户名: test, 密码: 123456）
async function createDefaultUser() {
  const existingUser = await getUserByUsername('test');
  if (!existingUser) {
    // 密码通过 bcrypt 哈希存储，绝不保存明文密码
    const passwordHash = await bcrypt.hash('123456', 10);
    db.run(
      'INSERT INTO users (username, password_hash) VALUES (?, ?)',
      ['test', passwordHash],
      (err) => {
        if (err) {
          console.error('创建测试账号失败:', err.message);
        } else {
          console.log('默认测试账号已创建 (用户名: test, 密码: 123456)');
        }
      }
    );
  }
}

// 根据用户名查找用户
function getUserByUsername(username) {
  return new Promise((resolve, reject) => {
    db.get('SELECT * FROM users WHERE username = ?', [username], (err, row) => {
      if (err) reject(err);
      else resolve(row);
    });
  });
}

// 验证密码（使用 bcrypt 比较哈希值）
async function verifyPassword(user, password) {
  // 将用户输入的明文密码与存储的哈希密码进行比较
  return await bcrypt.compare(password, user.password_hash);
}

module.exports = {
  db,
  getUserByUsername,
  verifyPassword
};
```

