登录接口 + 建表（纯净版，无注册）：

```javascript
const express = require('express');
const sqlite3 = require('sqlite3').verbose();
const crypto = require('crypto');

const app = express();
app.use(express.json());

// 创建 users 表（仅用户名 + 密码哈希字段）
// 字段说明：
// - username: 用户名，TEXT，唯一且非空
// - password_hash: 密码哈希，TEXT，非空（格式为 salt:hash，不存明文密码）
const db = new sqlite3.Database('./users.db');
db.run(`CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL
)`);

// 登录接口：接收用户名和密码并校验
app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) {
    return res.status(400).json({ error: '用户名和密码必填' });
  }
  const row = await db.get('SELECT * FROM users WHERE username = ?', [username]);
  if (!row) {
    return res.status(401).json({ error: '用户名或密码错误' });
  }
  const [salt, storedHash] = row.password_hash.split(':');
  const hash = crypto.pbkdf2Sync(password, salt, 100000, 64, 'sha512').toString('hex');
  if (hash !== storedHash) {
    return res.status(401).json({ error: '用户名或密码错误' });
  }
  res.json({ message: '登录成功', userId: row.id });
});

app.listen(3000, () => console.log('登录服务运行在 http://localhost:3000'));
```

**说明：**
- 建表独立成段，带注释标明 username 和 password_hash 字段
- 密码以 `salt:hash` 格式存储（PBKDF2 哈希），非明文
- 仅登录功能，无注册/忘记密码/第三方登录等额外功能

